from qbank_authoring import ref
PR=ref('ADA Standards—2026: Prevention or Delay of Diabetes','https://doi.org/10.2337/dc26-s003')
TZ=ref('TZIELD (teplizumab): U.S. Prescribing Information, 2026','https://www.accessdata.fda.gov/drugsatfda_docs/label/2026/761183s013lbl.pdf')
q('What is the preferred ADA 2026 screening approach for cystic fibrosis–related diabetes when feasible?', 'Annual OGTT beginning by age 10 years',[
 ('A normal A1C alone definitively excludes CFRD','A1C alone can miss clinically important postload hyperglycemia.'),('Screen only after age 35 as for routine adult type 2 testing','Cystic fibrosis has a specific earlier pathway.'),('Urine glucose is the preferred annual test','It is insufficiently sensitive and not the preferred screening method.')],
 'A high-risk pancreatic phenotype needs a tailored screening test', '**OGTT is preferred for annual CFRD screening from age ten.**',['CFRD differs from ordinary type 1 and type 2 diabetes.','The 2026 guidance includes an alternative two-step strategy when OGTT is not feasible.'], '**Do not use a normal A1C as a universal exclusion.**',['Interpret testing during clinical stability when possible.','Nutritional and pulmonary status matter in management.'],[['Condition','Cystic fibrosis'],['Preferred test','Annual OGTT'],['Starting age','By ten years']],[DX])
q('Hyperglycemia develops in the immediate postoperative period after kidney transplantation. Which statement is most accurate?', 'Treat the hyperglycemia now, but diagnose persistent posttransplant diabetes after clinical and immunosuppressive stabilization',[
 ('Every early high glucose permanently establishes posttransplant diabetes','Surgical stress and high-dose steroids can produce transient hyperglycemia.'),('All treatment should wait until long-term diagnosis is possible','Immediate clinically important hyperglycemia still needs care.'),('A1C is always the best early test despite transfusion or anemia','These can confound A1C in the early period.')],
 'Transient stress and persistent disease must be distinguished', '**Immunosuppression, stress and pre-existing metabolic risk all contribute.**',['Tacrolimus and glucocorticoids can impair glucose regulation.','OGTT is useful in the stable diagnostic phase.'], '**Manage current risk while planning reassessment.**',['Do not withdraw essential immunosuppression without the transplant team.','Use a diagnostic method appropriate to red-cell and renal status.'],[['Early phase','Stress and treatment effects'],['Persistent diagnosis','Stable reassessment'],['Care now','Treat significant hyperglycemia']],[DX],'clinical_scenario')
q('A patient taking morning prednisolone has fasting glucose 105 mg/dL but marked late-afternoon hyperglycemia. Which interpretation is best?', 'The timing is compatible with glucocorticoid-associated hyperglycemia',[
 ('A normal fasting result excludes steroid-related dysglycemia','Morning fasting values can miss later excursions.'),('The afternoon value is automatically an assay artifact','The steroid pharmacodynamic pattern can explain it.'),('Only nocturnal measurements are useful','Monitoring should capture the expected period of hyperglycemia.')],
 'Match monitoring to the drug exposure', '**Morning intermediate-acting glucocorticoids often raise glucose later in the day.**',['Longer-acting or repeated doses can cause more sustained hyperglycemia.','Previously unrecognized diabetes can coexist.'], '**Tailor monitoring and therapy to the steroid schedule.**',['Reduce glucose-lowering doses as steroids taper when needed.','Avoid relying on fasting glucose alone.'],[['Morning prednisolone','Often later-day rise'],['Long-acting/repeated steroid','More sustained effect'],['Monitoring','Capture the expected excursion']],[DX],'clinical_scenario')
q('A patient receiving an immune checkpoint inhibitor develops abrupt insulin-deficient diabetes and DKA with only a modestly elevated A1C. Which explanation is most likely?', 'Rapid immune-mediated beta-cell loss',[
 ('A modest A1C rules out genuine severe hyperglycemia','A1C may not reflect a very recent abrupt onset.'),('The condition is necessarily ordinary gradual type 2 diabetes','Checkpoint-associated autoimmune or immune-mediated insulin deficiency is a recognized phenotype.'),('All such cases can safely be managed without insulin','Severe insulin deficiency requires insulin treatment.')],
 'Cancer immunotherapy can produce a sudden endocrine emergency', '**Checkpoint-inhibitor-associated diabetes can present rapidly with ketosis.**',['Islet antibodies are not positive in every case.','A low C-peptide supports severe secretory failure in the correct setting.'], '**Treat DKA promptly and coordinate oncology/endocrine care.**',['Long-term insulin need is common.','Do not let a modest A1C create false reassurance.'],[['Exposure','Immune checkpoint inhibitor'],['Onset','Can be abrupt'],['Risk','Insulin deficiency and DKA']],[DX],'clinical_scenario')
q('An adult with an insulin-resistant phenotype presents with DKA but later has negative islet antibodies and substantial recovery of C-peptide. Which classification approach is most useful?', 'Assess ketosis-prone diabetes using autoimmunity and beta-cell reserve',[
 ('DKA proves lifelong complete autoimmune insulin deficiency in every patient','Some ketosis-prone phenotypes recover secretion.'),('Insulin can be stopped at discharge without reassessment','Withdrawal requires demonstrated recovery and a supervised plan.'),('Obesity means the initial DKA did not require insulin','Acute DKA requires standard emergency treatment.')],
 'Presentation and long-term physiology need not be identical', '**Autoantibody and beta-cell-reserve assessment helps classify ketosis-prone diabetes.**',['Severe glucotoxicity can transiently suppress secretion.','The course varies among subgroups.'], '**Use reassessment after recovery to plan therapy.**',['Some patients can reduce insulin under supervision.','Maintain sick-day education and monitor for relapse.'],[['Acute phase','Treat DKA'],['Classification','Autoimmunity plus reserve'],['Later therapy','Depends on recovery and risk']],[DX,T1],'clinical_scenario')
q('Multiple confirmed islet autoantibodies are present with normoglycemia and no diabetes symptoms. Which classic autoimmune diabetes stage is described?', 'Stage 1 type 1 diabetes',[
 ('Stage 2','Stage 2 includes dysglycemia.'),('Stage 3','Stage 3 meets overt diagnostic glycemic criteria.'),('No autoimmune disease can exist before symptoms','Presymptomatic autoimmune stages are recognized.')],
 'Autoimmune diabetes can be detected before clinical hyperglycemia', '**Stage 1 combines multiple islet autoantibodies with normoglycemia.**',['A single antibody has a different risk interpretation.','Progression risk requires structured counseling and surveillance.'], '**Offer appropriate education and follow-up.**',['Monitoring can reduce unexpected DKA at progression.','Use specialist pathways for confirmatory testing and family screening.'],[['Stage 1','Autoimmunity plus normoglycemia'],['Stage 2','Autoimmunity plus dysglycemia'],['Stage 3','Overt diabetes']],[DX,T1])
q('Multiple islet autoantibodies and dysglycemia are confirmed, but overt stage 3 diabetes criteria have not been met. Which stage is present?', 'Stage 2 type 1 diabetes',[
 ('Stage 1','Stage 1 has normoglycemia.'),('Stage 3 solely because two antibodies are present','Overt glycemic criteria distinguish stage 3.'),('Ordinary type 2 prediabetes without autoimmune significance','The antibody pattern identifies presymptomatic autoimmune disease.')],
 'Dysglycemia marks progression within presymptomatic autoimmune disease', '**Stage 2 has a higher near-term progression risk than stage 1.**',['Repeated or protocol-defined testing confirms the stage.','Symptoms and overt hyperglycemia require assessment for progression.'], '**Discuss monitoring and disease-modifying treatment eligibility.**',['Eligibility depends on the current local indication and patient factors.','Do not describe delay of progression as a permanent cure.'],[['Antibodies','Multiple confirmed'],['Glycemia','Abnormal but below overt stage 3'],['Implication','Closer surveillance and eligibility review']],[DX,TZ])
q('Which statement accurately reflects the 2026 U.S. teplizumab label for delaying stage 3 type 1 diabetes?', 'It is a CD3-directed therapy for eligible people aged one year or older with confirmed stage 2 disease',[
 ('It permanently replaces insulin in all established stage 3 diabetes','The delay indication is not a universal insulin replacement or cure.'),('It is a GLP-1 receptor agonist for type 2 prevention','It targets CD3-mediated immune pathways.'),('The original eight-year minimum applies unchanged to every jurisdiction and date','The 2026 U.S. label expanded the age range; local labels can differ.')],
 'A current product label can differ from an older textbook statement', '**The 2026 U.S. indication includes age one year and above for stage 2 disease.**',['The purpose is delaying progression to stage 3.','Screening, vaccination and infection precautions are required.'], '**Check the applicable local authorization and full safety criteria.**',['Do not transfer U.S. approval directly to another country.','Counsel about monitoring, infusion reactions and the limits of benefit.'],[['Target','CD3'],['Stage','Confirmed stage 2'],['2026 U.S. age','At least one year']],[TZ])
q('Why does insulin resistance not invariably produce diabetes immediately?', 'Beta cells can initially compensate by increasing insulin secretion',[
 ('Insulin resistance always leaves glucose unchanged permanently','Compensation can eventually fail.'),('All insulin resistance is caused by complete beta-cell destruction','Resistance and secretory deficiency are distinct interacting processes.'),('Glucagon has no role in glucose regulation','Inappropriate glucagon can contribute to hyperglycemia.')],
 'Type 2 diabetes reflects failure of compensation as well as resistance', '**Relative beta-cell dysfunction becomes inadequate for the degree of resistance.**',['Hepatic glucose production and peripheral uptake are both important.','Genetics, adiposity and ectopic fat contribute variably.'], '**Choose treatment for the whole cardiometabolic phenotype.**',['Weight management can improve insulin sensitivity.','Progressive secretory loss may eventually require insulin.'],[['Early resistance','Compensatory hyperinsulinemia'],['Progression','Insufficient secretion for demand'],['Clinical disease','Combined metabolic defects']],[DX])
q('An adolescent with obesity has acanthosis nigricans and dysglycemia. What does the skin finding most strongly suggest?', 'An insulin-resistant phenotype',[
 ('Complete absence of endogenous insulin as a direct conclusion','Acanthosis commonly accompanies hyperinsulinemia and resistance.'),('A specific MODY gene is established','The skin finding does not identify a molecular subtype.'),('Autoimmune diabetes is impossible','Resistance and autoimmune disease can coexist.')],
 'A physical sign informs probability rather than proving type', '**Hyperinsulinemia is associated with acanthosis nigricans.**',['Family history and metabolic comorbidity refine assessment.','Atypical course still warrants classification testing.'], '**Assess glycemia and related risks.**',['Avoid stigmatizing explanations.','Use a family-centered nutrition, activity and treatment plan.'],[['Sign','Acanthosis nigricans'],['Association','Insulin resistance'],['Limitation','Not an absolute subtype test']],[DX],'clinical_scenario')
q('Under ADA 2026 guidance, which asymptomatic adult merits risk-based testing before age 35?', 'An adult of Asian ancestry with BMI 24 kg/m² and a first-degree relative with diabetes',[
 ('Testing must wait until age 35 in everyone','Earlier testing is appropriate with overweight and additional risks.'),('Asian ancestry requires BMI at least 30 before testing','The risk-based BMI threshold is lower, at least 23.'),('Family history never affects testing timing','It is an established risk factor.')],
 'Screening thresholds account for differential risk', '**ADA recommends considering testing at any adult age with overweight or obesity plus risk factors.**',['The BMI threshold is at least 23 for Asian ancestry.','Otherwise routine screening begins at age 35.'], '**Choose a suitable plasma glucose or A1C test.**',['Testing frequency depends on results and evolving risk.','A normal test does not eliminate future risk.'],[['Asian ancestry threshold','BMI at least 23'],['Additional risk','First-degree relative'],['Universal adult age','Begin by 35']],[DX],'clinical_scenario')
q('Which intervention best reflects a structured diabetes prevention program for an adult with overweight and high-risk prediabetes?', 'A sustained reduced-calorie eating plan targeting about 5–7% weight loss and at least 150 minutes of moderate activity weekly',[
 ('A brief instruction to avoid sugar without follow-up','Effective programs provide structured behavioral support.'),('Mandatory extreme carbohydrate exclusion for every participant','No single eating pattern is required for all.'),('Physical activity only after normal glucose is restored','Activity is part of prevention itself.')],
 'Behavioral support translates goals into sustained change', '**Modest sustained weight loss and regular activity reduce progression risk.**',['The original DPP targeted at least 7% weight loss and 150 minutes weekly.','Nutrition should fit culture, preferences and comorbidity.'], '**Address cardiovascular risk alongside glycemia.**',['Support sleep, tobacco cessation and accessible activity.','Follow glycemia and barriers over time rather than treating education as a one-time event.'],[['Weight','Sustained 5–7% or more when appropriate'],['Activity','At least 150 minutes/week'],['Delivery','Structured ongoing support']],[PR])
q('Which prediabetes profile particularly supports considering metformin for prevention in addition to lifestyle treatment?', 'Age 42 years, BMI 37 kg/m², fasting glucose 116 mg/dL and prior gestational diabetes',[
 ('An older lean adult with consistently normal glycemia','This does not match the high-risk prevention profile.'),('Any person with one normal glucose measurement','Metformin is not universal prevention for normal glycemia.'),('Confirmed symptomatic insulin-deficient diabetes as a substitute for insulin','That requires treatment of established insulin deficiency, not a prevention-only approach.')],
 'Prevention pharmacotherapy is selective', '**ADA emphasizes high-risk adults, especially ages 25–59 with BMI at least 35, higher glycemia or prior GDM.**',['Lifestyle support remains important.','Renal function, tolerance and contraindications affect suitability.'], '**Explain that risk reduction is not guaranteed prevention.**',['Monitor glycemia and long-term tolerability.','Consider vitamin B12 assessment with prolonged treatment, especially with anemia or neuropathy.'],[['Higher-risk features','Obesity and elevated fasting/A1C'],['History','Prior gestational diabetes'],['Plan','Lifestyle plus selected metformin']],[PR],'clinical_scenario')
q('A patient on prolonged metformin develops anemia and distal sensory symptoms. Which reversible contributor should be evaluated?', 'Vitamin B12 deficiency',[
 ('Every sensory symptom must be irreversible diabetic neuropathy','A treatable nutritional contributor can coexist.'),('Metformin invariably causes folate excess explaining neuropathy','This is not the relevant recognized association.'),('Normal glucose excludes any vitamin deficiency','Vitamin deficiency is independent of current glycemia.')],
 'Do not attribute every neuropathic symptom to diabetes', '**Long-term metformin use can lower vitamin B12.**',['Anemia and neurological symptoms strengthen the indication to test.','Other nutritional, renal and neurological causes also require consideration.'], '**Treat confirmed deficiency and review the overall regimen.**',['Metformin does not necessarily need permanent cessation if otherwise appropriate.','Use follow-up to assess hematological and clinical response.'],[['Exposure','Long-term metformin'],['Clues','Anemia or neuropathy'],['Action','Assess and correct B12 deficiency']],[PR],'clinical_scenario')
q('After substantial sustained weight loss, an adult with prior type 2 diabetes has A1C below 6.5% for at least three months without glucose-lowering medication. Which term is preferred?', 'Diabetes remission',[
 ('Permanent cure requiring no further follow-up','Relapse and complication risks remain.'),('Proof that the original diagnosis was always incorrect','Genuine type 2 diabetes can enter remission.'),('Active diabetes cannot ever improve without medication','Weight loss or metabolic surgery can produce remission in selected patients.')],
 'Remission recognizes improvement without erasing future risk', '**The consensus definition uses A1C below 6.5% at least three months after stopping glucose-lowering therapy.**',['Alternative criteria may be needed when A1C is unreliable.','Weight regain, illness and progressive beta-cell dysfunction can lead to recurrence.'], '**Continue surveillance and complication care.**',['Maintain preventive cardiovascular assessment.','Avoid presenting remission as a reason to abandon support.'],[['Term','Remission'],['Typical criterion','A1C below 6.5% off therapy for at least three months'],['Follow-up','Still required']],[PR])
q('A woman had gestational diabetes but normal postpartum testing. What is the correct long-term implication?', 'She remains at increased future diabetes risk and needs periodic lifelong screening and prevention support',[
 ('A normal postpartum result eliminates future risk','Risk remains increased.'),('Gestational diabetes automatically proves permanent type 1 diabetes','It does not establish that classification.'),('Screening is only needed if symptoms develop','Asymptomatic screening is appropriate.')],
 'Pregnancy can reveal limited metabolic reserve', '**Prior GDM identifies a high-risk prevention group.**',['A postpartum test establishes current status rather than lifetime risk.','Future pregnancy planning is another reason for reassessment.'], '**Continue weight, activity and cardiovascular risk support.**',['Use ongoing testing at recommended intervals.','Metformin prevention can be considered in suitable high-risk individuals.'],[['Postpartum normal test','Current status'],['Long-term risk','Still elevated'],['Care','Lifelong periodic screening and prevention']],[DX,PR],'clinical_scenario')
